package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

type FunctionInfo struct {
	Name       string
	IsMethod   bool
	Receiver   *TypeInfo
	Params     []*ParamInfo
	Results    []*TypeInfo
	IsGeneric  bool
	TypeParams []string
}

type ParamInfo struct {
	Name     string
	Type     *TypeInfo
	IsVariadic bool
}

type TypeInfo struct {
	Name       string
	IsPointer  bool
	IsSlice    bool
	IsMap      bool
	IsVariadic bool
	Generic    *GenericInfo
	Fields     map[string]*TypeInfo // for struct fields
}

type GenericInfo struct {
	Name       string
	Args       []string
	Constraint string
}

type ParsedFile struct {
	Package   string
	Functions []FunctionInfo
}

type Parser struct {
	fset *token.FileSet
}

func NewParser() *Parser {
	return &Parser{
		fset: token.NewFileSet(),
	}
}

func (p *Parser) Parse(source string) (*ParsedFile, error) {
	file, err := parser.ParseFile(p.fset, "", source, parser.ParseComments)
	if err != nil {
		return nil, err
	}

	var packageName string
	if file.Name != nil {
		packageName = file.Name.Name
	}

	var funcs []FunctionInfo

	for _, decl := range file.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			fn := p.parseFuncDecl(d)
			if fn != nil {
				funcs = append(funcs, *fn)
			}
		}
	}

	return &ParsedFile{
		Package:   packageName,
		Functions: funcs,
	}, nil
}

func (p *Parser) parseFuncDecl(fn *ast.FuncDecl) *FunctionInfo {
	info := &FunctionInfo{
		Name:     fn.Name.Name,
		IsMethod: fn.Recv != nil,
	}

	// Parse receiver if it's a method
	if fn.Recv != nil && len(fn.Recv.List) > 0 {
		info.Receiver = p.parseType(fn.Recv.List[0].Type)
	}

	// Parse type parameters
	if fn.Type.TypeParams != nil && len(fn.Type.TypeParams.List) > 0 {
		info.IsGeneric = true
		for _, tp := range fn.Type.TypeParams.List {
			if ident, ok := tp.Type.(*ast.Ident); ok {
				info.TypeParams = append(info.TypeParams, ident.Name)
			}
		}
	}

	// Parse parameters
	if fn.Type.Params != nil {
		for _, field := range fn.Type.Params.List {
			typeInfo := p.parseType(field.Type)
			if len(field.Names) == 0 {
				// Unnamed parameter
				info.Params = append(info.Params, &ParamInfo{
					Name: "",
					Type: typeInfo,
				})
			} else {
				for _, name := range field.Names {
					info.Params = append(info.Params, &ParamInfo{
						Name: name.Name,
						Type: typeInfo,
					})
				}
			}
		}
	}

	// Parse return types
	if fn.Type.Results != nil {
		for _, field := range fn.Type.Results.List {
			info.Results = append(info.Results, p.parseType(field.Type))
		}
	}

	return info
}

func (p *Parser) parseType(expr ast.Expr) *TypeInfo {
	switch t := expr.(type) {
	case *ast.Ident:
		return &TypeInfo{Name: t.Name}
	case *ast.StarExpr:
		inner := p.parseType(t.X)
		inner.IsPointer = true
		return inner
	case *ast.ArrayType:
		inner := p.parseType(t.Elt)
		inner.IsSlice = true
		return inner
	case *ast.MapType:
		// For map, we just track it's a map
		inner := p.parseType(t.Value)
		inner.IsMap = true
		return inner
	case *ast.IndexExpr:
		// Handle generic types like Set[string]
		return p.parseIndexExpr(t)
	case *ast.IndexListExpr:
		// Handle multiple generic parameters like Map[string, int]
		return p.parseIndexListExpr(t)
	case *ast.SelectorExpr:
		// Handle package.Type
		if x, ok := t.X.(*ast.Ident); ok {
			return &TypeInfo{Name: x.Name + "." + t.Sel.Name}
		}
		return &TypeInfo{Name: "interface{}"}
	case *ast.FuncType:
		return &TypeInfo{Name: "func"}
	case *ast.InterfaceType:
		return &TypeInfo{Name: "interface{}"}
	default:
		return &TypeInfo{Name: "interface{}"}
	}
}

func (p *Parser) parseIndexExpr(t *ast.IndexExpr) *TypeInfo {
	var baseName string
	if ident, ok := t.X.(*ast.Ident); ok {
		baseName = ident.Name
	}

	var args []string
	if ident, ok := t.Index.(*ast.Ident); ok {
		args = append(args, ident.Name)
	}

	return &TypeInfo{
		Name: baseName,
		Generic: &GenericInfo{
			Name: baseName,
			Args: args,
		},
	}
}

func (p *Parser) parseIndexListExpr(t *ast.IndexListExpr) *TypeInfo {
	var baseName string
	if ident, ok := t.X.(*ast.Ident); ok {
		baseName = ident.Name
	}

	var args []string
	for _, index := range t.Indices {
		if ident, ok := index.(*ast.Ident); ok {
			args = append(args, ident.Name)
		}
	}

	return &TypeInfo{
		Name: baseName,
		Generic: &GenericInfo{
			Name: baseName,
			Args: args,
		},
	}
}

func (t *TypeInfo) String() string {
	if t.Generic != nil {
		result := t.Generic.Name
		if len(t.Generic.Args) > 0 {
			result += "["
			for i, arg := range t.Generic.Args {
				if i > 0 {
					result += ", "
				}
				result += arg
			}
			result += "]"
		}
		if t.IsPointer {
			result = "*" + result
		}
		if t.IsSlice {
			result = "[]" + result
		}
		return result
	}

	result := ""
	if t.IsPointer {
		result += "*"
	}
	if t.IsSlice {
		result += "[]"
	}
	if t.IsMap {
		result += "map["
	}
	result += t.Name
	if t.IsMap {
		result += "]interface{}"
	}
	return result
}
