cat > /workspace/generator.go << 'EOF'
package main

import (
	"fmt"
	"sort"
	"strings"
)

type GeneratorOptions struct {
	PrintInputs bool
	Named       bool
	NoSubtests  bool
	Parallel    bool
	UseCmp      bool
}

type Generator struct {
	opts *GeneratorOptions
}

func NewGenerator(opts *GeneratorOptions) *Generator {
	return &Generator{opts: opts}
}

func (g *Generator) Generate(packageName string, funcs []FunctionInfo) (string, error) {
	var buf strings.Builder

	// Write package declaration
	fmt.Fprintf(&buf, "package %s\n\n", packageName)

	// Collect all imports needed
	imports := g.collectImports(funcs)

	// Write imports
	if len(imports) > 0 {
		fmt.Fprintf(&buf, "import (\n")
		for _, imp := range imports {
			fmt.Fprintf(&buf, "\t\"%s\"\n", imp)
		}
		fmt.Fprintf(&buf, ")\n\n")
	}

	// Generate test for each function
	for _, fn := range funcs {
		testName := g.generateTestName(fn)
		fmt.Fprintf(&buf, "Generated %s\n", testName)

		testCode := g.generateTestFunc(fn)
		fmt.Fprintf(&buf, "%s\n", testCode)
	}

	return buf.String(), nil
}

func (g *Generator) collectImports(funcs []FunctionInfo) []string {
	imports := make(map[string]bool)
	imports["testing"] = true
	return []string{"testing"}
}

func (g *Generator) generateTestName(fn FunctionInfo) string {
	if fn.IsMethod && fn.Receiver != nil {
		// For methods, generate TestReceiver_MethodName
		receiverName := fn.Receiver.Name
		if fn.Receiver.IsPointer {
			receiverName = strings.TrimPrefix(receiverName, "*")
		}
		return fmt.Sprintf("Test%s_%s", receiverName, fn.Name)
	}
	return fmt.Sprintf("Test%s", fn.Name)
}

func (g *Generator) generateTestFunc(fn FunctionInfo) string {
	var buf strings.Builder

	testName := g.generateTestName(fn)
	fmt.Fprintf(&buf, "func %s(t *testing.T) {\n", testName)

	// Add t.Parallel() if needed
	if g.opts.Parallel && !g.opts.NoSubtests {
		fmt.Fprintf(&buf, "\tt.Parallel()\n")
	}

	// Generate type structs
	g.generateTypeStructs(&buf, fn)

	// Generate tests slice/map
	g.generateTestsDeclaration(&buf, fn)

	// Generate loop
	g.generateLoopAndCall(&buf, fn)

	fmt.Fprintf(&buf, "}\n\n")

	return buf.String()
}

func (g *Generator) generateTypeStructs(buf *strings.Builder, fn FunctionInfo) {
	// For methods, we need a fields struct
	if fn.IsMethod && fn.Receiver != nil {
		fmt.Fprintf(buf, "\ttype fields struct {\n")
		// Add receiver fields - just the receiver type
		if fn.Receiver != nil {
			// For simplicity, we'll just add a single field with the receiver type
			recvName := fn.Receiver.Name
			if fn.Receiver.IsPointer {
				recvName = strings.TrimPrefix(recvName, "*")
			}
			// For generic receivers, extract the base type
			if fn.Receiver.Generic != nil {
				recvName = fn.Receiver.Generic.Name
			}
			// We don't actually add fields for the struct itself in the generated tests
			// Instead, we'll add them if the receiver is a struct (but we can't know that from parsing)
		}
		fmt.Fprintf(buf, "\t}\n")
	}

	// For functions with parameters, we need an args struct
	if len(fn.Params) > 0 {
		fmt.Fprintf(buf, "\ttype args struct {\n")
		for _, param := range fn.Params {
			if param.Name != "" {
				fmt.Fprintf(buf, "\t\t%s %s\n", param.Name, param.Type.String())
			}
		}
		fmt.Fprintf(buf, "\t}\n")
	}
}

func (g *Generator) generateTestsDeclaration(buf *strings.Builder, fn FunctionInfo) {
	if g.opts.Named {
		fmt.Fprintf(buf, "\ttests := map[string]struct {\n")
	} else {
		fmt.Fprintf(buf, "\ttests := []struct {\n")
	}

	fmt.Fprintf(buf, "\t\tname string\n")

	// For methods, add fields
	if fn.IsMethod && fn.Receiver != nil {
		fmt.Fprintf(buf, "\t\ts *%s\n", g.getReceiverTypeName(fn.Receiver))
	}

	// Add args field if there are parameters
	if len(fn.Params) > 0 {
		fmt.Fprintf(buf, "\t\targs args\n")
	}

	// Add return value fields
	for i, result := range fn.Results {
		if len(fn.Results) == 1 {
			if i == len(fn.Results)-1 && strings.HasPrefix(result.String(), "error") {
				fmt.Fprintf(buf, "\t\twantErr bool\n")
			} else {
				fmt.Fprintf(buf, "\t\twant %s\n", result.String())
			}
		} else {
			if strings.HasPrefix(result.String(), "error") {
				fmt.Fprintf(buf, "\t\twantErr bool\n")
			} else {
				fmt.Fprintf(buf, "\t\twant%d %s\n", i, result.String())
			}
		}
	}

	if g.opts.Named {
		fmt.Fprintf(buf, "\t}{\n")
		fmt.Fprintf(buf, "\t\t// TODO: Add test cases.\n")
		fmt.Fprintf(buf, "\t}\n")
	} else {
		fmt.Fprintf(buf, "\t}{\n")
		fmt.Fprintf(buf, "\t\t// TODO: Add test cases.\n")
		fmt.Fprintf(buf, "\t}\n")
	}
}

func (g *Generator) generateLoopAndCall(buf *strings.Builder, fn FunctionInfo) {
	if g.opts.Named {
		fmt.Fprintf(buf, "\tfor name, tt := range tests {\n")
	} else {
		fmt.Fprintf(buf, "\tfor _, tt := range tests {\n")
	}

	if g.opts.NoSubtests {
		// No subtests - direct call
		g.generateFunctionCall(buf, fn, false, true)
	} else {
		// With subtests
		fmt.Fprintf(buf, "\t\tt.Run(tt.name, func(t *testing.T) {\n")

		if g.opts.Parallel {
			fmt.Fprintf(buf, "\t\t\tt.Parallel()\n")
		}

		g.generateFunctionCall(buf, fn, true, false)

		fmt.Fprintf(buf, "\t\t})\n")
	}

	fmt.Fprintf(buf, "\t}\n")
}

func (g *Generator) generateFunctionCall(buf *strings.Builder, fn FunctionInfo, inSubtest bool, noSubtests bool) {
	indent := "\t\t"
	if inSubtest {
		indent = "\t\t\t"
	}

	// Build the function call
	var callArgs []string
	if fn.IsMethod && fn.Receiver != nil {
		// Add receiver initialization
		recvType := g.getReceiverTypeName(fn.Receiver)
		fmt.Fprintf(buf, "%sc := &%s{}\n", indent, recvType)
	}

	for _, param := range fn.Params {
		if param.Name != "" {
			callArgs = append(callArgs, fmt.Sprintf("tt.args.%s", param.Name))
		}
	}

	// Generate the function call
	var callStr string
	if fn.IsMethod {
		recvType := g.getReceiverTypeName(fn.Receiver)
		if fn.Receiver.Generic != nil && len(fn.Receiver.Generic.Args) > 0 {
			// For generic methods, need to instantiate with string type
			callStr = fmt.Sprintf("c.%s(%s)", fn.Name, strings.Join(callArgs, ", "))
		} else {
			callStr = fmt.Sprintf("c.%s(%s)", fn.Name, strings.Join(callArgs, ", "))
		}
	} else {
		// For generic functions
		if fn.IsGeneric {
			callStr = fmt.Sprintf("%s[string](%s)", fn.Name, strings.Join(callArgs, ", "))
		} else {
			callStr = fmt.Sprintf("%s(%s)", fn.Name, strings.Join(callArgs, ", "))
		}
	}

	numResults := len(fn.Results)

	if numResults == 0 {
		// No return values
		fmt.Fprintf(buf, "%s%s\n", indent, callStr)
	} else if numResults == 1 {
		result := fn.Results[0]
		if strings.HasPrefix(result.String(), "error") {
			// Single error return
			fmt.Fprintf(buf, "%serr := %s\n", indent, callStr)
			fmt.Fprintf(buf, "%sif err != nil {\n", indent)
			fmt.Fprintf(buf, "%s\tt.Errorf(\"%s() error = %%v, want nil\", err)\n", indent, fn.Name)
			fmt.Fprintf(buf, "%s}\n", indent)
		} else {
			// Single non-error return
			fmt.Fprintf(buf, "%sgot := %s\n", indent, callStr)
			if noSubtests {
				if g.opts.PrintInputs {
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%%q. %s(%s) = %%v, want %%v\", tt.name", indent, fn.Name)
					for _, param := range fn.Params {
						if param.Name != "" {
							fmt.Fprintf(buf, ", tt.args.%s", param.Name)
						}
					}
					fmt.Fprintf(buf, ", got, tt.want)\n")
					fmt.Fprintf(buf, "%s}\n", indent)
				} else {
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%%q. %s() = %%v, want %%v\", tt.name, got, tt.want)\n", indent, fn.Name)
					fmt.Fprintf(buf, "%s}\n", indent)
				}
			} else {
				if g.opts.PrintInputs {
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%s(%s) = %%v, want %%v\"", indent, fn.Name)
					for _, param := range fn.Params {
						if param.Name != "" {
							fmt.Fprintf(buf, ", tt.args.%s", param.Name)
						}
					}
					fmt.Fprintf(buf, ", got, tt.want)\n")
					fmt.Fprintf(buf, "%s}\n", indent)
