package main

import (
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

var (
	all                  = flag.Bool("all", false, "generate tests for all functions and methods")
	excl                 = flag.String("excl", "", "regexp. generate tests for functions and methods that don't match. Takes precedence over -only, -exported, and -all")
	exported             = flag.Bool("exported", false, "generate tests for exported functions and methods. Takes precedence over -only and -all")
	printInputs          = flag.Bool("i", false, "print test inputs in error messages")
	named                = flag.Bool("named", false, "switch table tests from using slice to map (with test name for the key)")
	nosubtests           = flag.Bool("nosubtests", false, "disable generating tests using the Go 1.7 subtests feature")
	parallel             = flag.Bool("parallel", false, "enable generating parallel subtests using the Go 1.7 feature")
	write                = flag.Bool("w", false, "write output to (test) files instead of stdout")
	templateDir          = flag.String("template_dir", "", "optional. Path to a directory containing custom test code templates. Takes precedence over -template. This can also be set via environment variable GOTESTS_TEMPLATE_DIR")
	templateName         = flag.String("template", "", "optional. Specify custom test code templates, e.g. testify. This can also be set via environment variable GOTESTS_TEMPLATE")
	templateParamsFile   = flag.String("template_params_file", "", "read external parameters to template by json with file")
	templateParams       = flag.String("template_params", "", "read external parameters to template by json with stdin")
	only                 = flag.String("only", "", "regexp. generate tests for functions and methods that match only. Takes precedence over -all")
	useCmp               = flag.Bool("use_go_cmp", false, "use cmp.Equal (google/go-cmp) instead of reflect.DeepEqual")
	version              = flag.Bool("version", false, "print version information and exit")
	aiFlag               = flag.Bool("ai", false, "generate test cases using AI (requires Ollama)")
	aiModel              = flag.String("ai-model", "qwen2.5-coder:0.5b", "AI model to use for test generation")
	aiEndpoint           = flag.String("ai-endpoint", "http://localhost:11434", "Ollama API endpoint")
	aiMinCases           = flag.Int("ai-min-cases", 3, "minimum number of test cases to generate with AI")
	aiMaxCases           = flag.Int("ai-max-cases", 10, "maximum number of test cases to generate with AI")
)

func main() {
	flag.Parse()

	if *version {
		printVersion()
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		flag.Usage()
		os.Exit(1)
	}

	// Process each file/directory
	var filePaths []string
	for _, arg := range args {
		if arg == "./..." || arg == "..." {
			// Handle recursive pattern
			filePaths = append(filePaths, findGoFiles(".")...)
		} else if strings.HasSuffix(arg, "/...") {
			// Handle directory/... pattern
			dir := strings.TrimSuffix(arg, "/...")
			filePaths = append(filePaths, findGoFiles(dir)...)
		} else {
			// Check if it's a directory or file
			info, err := os.Stat(arg)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
			if info.IsDir() {
				filePaths = append(filePaths, findGoFilesInDir(arg)...)
			} else {
				filePaths = append(filePaths, arg)
			}
		}
	}

	for _, filePath := range filePaths {
		if *write {
			err := generateTestFile(filePath)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
		} else {
			err := generateAndPrintTests(filePath, os.Stdout)
			if err != nil {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				os.Exit(1)
			}
		}
	}
}

func printVersion() {
	fmt.Println("gotests v0.0.0-20260303205902-f3b63d74369a")
	fmt.Println("Go version: go1.24.5")
	fmt.Println("Git commit: f3b63d74369a8c405a9a3990a656a278a4f9096f")
	fmt.Println("Build time: 2026-03-03T20:59:02Z")
}

func findGoFiles(dir string) []string {
	var files []string
	filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return nil
		}
		if !info.IsDir() && strings.HasSuffix(path, ".go") && !strings.HasSuffix(path, "_test.go") {
			files = append(files, path)
		}
		return nil
	})
	return files
}

func findGoFilesInDir(dir string) []string {
	var files []string
	entries, err := os.ReadDir(dir)
	if err != nil {
		return files
	}
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".go") && !strings.HasSuffix(entry.Name(), "_test.go") {
			files = append(files, filepath.Join(dir, entry.Name()))
		}
	}
	return files
}

func generateAndPrintTests(filePath string, w io.Writer) error {
	source, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	testCode, err := GenerateTests(filePath, source)
	if err != nil {
		return err
	}

	_, err = w.Write([]byte(testCode))
	return err
}

func generateTestFile(filePath string) error {
	source, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	testCode, err := GenerateTests(filePath, source)
	if err != nil {
		return err
	}

	// Determine output filename
	dir := filepath.Dir(filePath)
	base := filepath.Base(filePath)
	baseWithoutExt := strings.TrimSuffix(base, ".go")
	testFileName := filepath.Join(dir, baseWithoutExt+"_test.go")

	return os.WriteFile(testFileName, []byte(testCode), 0644)
}

// GenerateTests generates test code for the given source file
func GenerateTests(filePath string, source []byte) (string, error) {
	parser := NewParser()
	file, err := parser.Parse(string(source))
	if err != nil {
		return "", err
	}

	funcs := filterFunctions(file.Functions)
	if len(funcs) == 0 {
		return "", nil
	}

	generator := NewGenerator(&GeneratorOptions{
		PrintInputs: *printInputs,
		Named:       *named,
		NoSubtests:  *nosubtests,
		Parallel:    *parallel,
		UseCmp:      *useCmp,
	})

	return generator.Generate(file.Package, funcs)
}

func filterFunctions(funcs []FunctionInfo) []FunctionInfo {
	var filtered []FunctionInfo

	// Build exclusion regex if needed
	var exclRegex *regexp.Regexp
	if *excl != "" {
		exclRegex = regexp.MustCompile(*excl)
	}

	// Determine which functions to include
	for _, fn := range funcs {
		// If -excl is set, exclude matching functions
		if exclRegex != nil && exclRegex.MatchString(fn.Name) {
			continue
		}

		// If -excl is set, include non-matching functions
		if exclRegex != nil {
			filtered = append(filtered, fn)
			continue
		}

		// If -only is set, only include matching functions
		if *only != "" {
			onlyRegex := regexp.MustCompile(*only)
			if onlyRegex.MatchString(fn.Name) {
				filtered = append(filtered, fn)
			}
			continue
		}

		// If -exported is set, only include exported functions
		if *exported {
			if isExported(fn.Name) {
				filtered = append(filtered, fn)
			}
			continue
		}

		// If -all is set, include all functions
		if *all {
			filtered = append(filtered, fn)
			continue
		}
	}

	return filtered
}

func isExported(name string) bool {
	if len(name) == 0 {
		return false
	}
	return name[0] >= 'A' && name[0] <= 'Z'
}
