					}
					fmt.Fprintf(buf, ")\n")
					fmt.Fprintf(buf, "%s}\n", indent)
				} else {
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%s() = %%v, want %%v\", got, tt.want)\n", indent, fn.Name)
					fmt.Fprintf(buf, "%s}\n", indent)
				}
			}
		}
	} else {
		// Multiple return values - check for error
		hasError := false
		errorIdx := -1
		for i, result := range fn.Results {
			if strings.HasPrefix(result.String(), "error") {
				hasError = true
				errorIdx = i
				break
			}
		}

		resultVars := []string{}
		for i := range fn.Results {
			resultVars = append(resultVars, fmt.Sprintf("got%d", i))
		}

		fmt.Fprintf(buf, "%s%s := %s\n", indent, strings.Join(resultVars, ", "), callStr)

