		fmt.Fprintf(&buf, ")\n\n")
	}

	// Generate test for each function
	for _, fn := range funcs {
		testCode := g.generateTestFunc(fn)
		fmt.Fprintf(&buf, "%s\n", testCode)
	}

	return buf.String(), nil
}

func (g *Generator) collectImports(funcs []FunctionInfo) []string {
	imports := make(map[string]bool)
	imports["testing"] = true
