	// Print generated messages to stdout along with the code
	for _, test := range generatedTests {
		fmt.Fprintf(w, "Generated %s\n", test)
	}

	_, err = w.Write([]byte(testCode))
	return err
}

func generateTestFile(filePath string) error {
	source, err := os.ReadFile(filePath)
	if err != nil {
		return err
	}

	testCode, generatedTests := GenerateTests(filePath, source)

	// Print generated messages to stdout
	for _, test := range generatedTests {
		fmt.Fprintf(os.Stdout, "Generated %s\n", test)
	}

	// Determine output filename
	dir := filepath.Dir(filePath)
	base := filepath.Base(filePath)
	baseWithoutExt := strings.TrimSuffix(base, ".go")
	testFileName := filepath.Join(dir, baseWithoutExt+"_test.go")

	return os.WriteFile(testFileName, []byte(testCode), 0644)
}

// GenerateTests generates test code for the given source file
// Returns the test code and a list of generated test names
func GenerateTests(filePath string, source []byte) (string, []string) {
	parser := NewParser()
	file, err := parser.Parse(string(source))
	if err != nil {
		return "", nil
	}

	funcs := filterFunctions(file.Functions)
	if len(funcs) == 0 {
		return "", nil
	}

	generator := NewGenerator(&GeneratorOptions{
		PrintInputs: *printInputs,
		Named:       *named,
		NoSubtests:  *nosubtests,
		Parallel:    *parallel,
		UseCmp:      *useCmp,
	})

	return generator.Generate(file.Package, funcs)
}

func filterFunctions(funcs []FunctionInfo) []FunctionInfo {
	var filtered []FunctionInfo

	// Build exclusion regex if needed
	var exclRegex *regexp.Regexp
	if *excl != "" {
		exclRegex = regexp.MustCompile(*excl)
	}

	// Determine which functions to include
	for _, fn := range funcs {
		// If -excl is set, exclude matching functions
		if exclRegex != nil && exclRegex.MatchString(fn.Name) {
			continue
		}

		// If -excl is set, include non-matching functions
		if exclRegex != nil {
			filtered = append(filtered, fn)
			continue
		}

		// If -only is set, only include matching functions
		if *only != "" {
			onlyRegex := regexp.MustCompile(*only)
			if onlyRegex.MatchString(fn.Name) {
				filtered = append(filtered, fn)
			}
			continue
		}

		// If -exported is set, only include exported functions
		if *exported {
			if isExported(fn.Name) {
				filtered = append(filtered, fn)
			}
			continue
		}

		// If -all is set, include all functions
		if *all {
			filtered = append(filtered, fn)
			continue
		}
	}

	return filtered
}

func isExported(name string) bool {
	if len(name) == 0 {
		return false
	}
	return name[0] >= 'A' && name[0] <= 'Z'
}
