		fmt.Fprintf(&buf, "\tt.Parallel()\n")
	}

	// Generate type structs
	g.generateTypeStructs(&buf, fn)

	// Generate tests slice/map
	g.generateTestsDeclaration(&buf, fn)

	// Generate loop
	g.generateLoopAndCall(&buf, fn)

	fmt.Fprintf(&buf, "}\n")

	return buf.String()
}

func (g *Generator) generateTypeStructs(buf *strings.Builder, fn FunctionInfo) {
	// For methods, we need a fields struct
	if fn.IsMethod && fn.Receiver != nil {
		fmt.Fprintf(buf, "\ttype fields struct {\n")
		fmt.Fprintf(buf, "\t}\n")
	}

	// For functions with parameters, we need an args struct
	if len(fn.Params) > 0 {
		fmt.Fprintf(buf, "\ttype args struct {\n")
		for _, param := range fn.Params {
			if param.Name != "" {
				paramType := g.substituteTypeParams(param.Type, fn.TypeParams)
				fmt.Fprintf(buf, "\t\t%s %s\n", param.Name, paramType.String())
			}
		}
		fmt.Fprintf(buf, "\t}\n")
	}
}

func (g *Generator) generateTestsDeclaration(buf *strings.Builder, fn FunctionInfo) {
	if g.opts.Named {
		fmt.Fprintf(buf, "\ttests := map[string]struct {\n")
	} else {
		fmt.Fprintf(buf, "\ttests := []struct {\n")
	}

	// Only add name field for slices, not maps
	if !g.opts.Named {
		fmt.Fprintf(buf, "\t\tname string\n")
	}

	// For methods, add receiver field
	if fn.IsMethod && fn.Receiver != nil {
		recvTypeName := g.getReceiverTypeName(fn.Receiver)
		fmt.Fprintf(buf, "\t\ts %s\n", recvTypeName)
	}

	// Add args field if there are parameters
	if len(fn.Params) > 0 {
		fmt.Fprintf(buf, "\t\targs args\n")
	}

	// Add return value fields
	for i, result := range fn.Results {
		if len(fn.Results) == 1 {
			if strings.HasPrefix(result.String(), "error") {
				fmt.Fprintf(buf, "\t\twantErr bool\n")
			} else {
				fmt.Fprintf(buf, "\t\twant %s\n", result.String())
			}
		} else {
			// Multiple return values
			if strings.HasPrefix(result.String(), "error") {
				fmt.Fprintf(buf, "\t\twantErr bool\n")
			} else {
				// For non-error values, check if there are any errors
				hasError := false
				for _, r := range fn.Results {
					if strings.HasPrefix(r.String(), "error") {
						hasError = true
						break
					}
				}
				if hasError {
					// If there's an error in the results, non-error values use "want"
					fmt.Fprintf(buf, "\t\twant %s\n", result.String())
				} else {
					// If no error, use want0, want1, etc.
					fmt.Fprintf(buf, "\t\twant%d %s\n", i, result.String())
				}
			}
		}
	}

	if g.opts.Named {
		fmt.Fprintf(buf, "\t}{\n")
		fmt.Fprintf(buf, "\t\t// TODO: Add test cases.\n")
		fmt.Fprintf(buf, "\t}\n")
	} else {
		fmt.Fprintf(buf, "\t}{\n")
		fmt.Fprintf(buf, "\t\t// TODO: Add test cases.\n")
		fmt.Fprintf(buf, "\t}\n")
	}
}

func (g *Generator) generateLoopAndCall(buf *strings.Builder, fn FunctionInfo) {
	if g.opts.Named {
		fmt.Fprintf(buf, "\tfor name, tt := range tests {\n")
	} else {
		fmt.Fprintf(buf, "\tfor _, tt := range tests {\n")
	}

	if g.opts.NoSubtests {
		// No subtests - direct call
		g.generateFunctionCall(buf, fn, false, true)
	} else {
		// With subtests
		if g.opts.Named {
			fmt.Fprintf(buf, "\t\tt.Run(name, func(t *testing.T) {\n")
		} else {
			fmt.Fprintf(buf, "\t\tt.Run(tt.name, func(t *testing.T) {\n")
		}

		if g.opts.Parallel {
			fmt.Fprintf(buf, "\t\t\tt.Parallel()\n")
		}

		g.generateFunctionCall(buf, fn, true, false)

		fmt.Fprintf(buf, "\t\t})\n")
	}

	fmt.Fprintf(buf, "\t}\n")
}

func (g *Generator) generateFunctionCall(buf *strings.Builder, fn FunctionInfo, inSubtest bool, noSubtests bool) {
	indent := "\t\t"
	if inSubtest {
		indent = "\t\t\t"
	}

	// Build the function call
	var callArgs []string
	if fn.IsMethod && fn.Receiver != nil {
		// Use receiver from test struct
		fmt.Fprintf(buf, "%sc := &%s{}\n", indent, g.getReceiverTypeNameNoPtr(fn.Receiver))
	}

	for _, param := range fn.Params {
		if param.Name != "" {
			callArgs = append(callArgs, fmt.Sprintf("tt.args.%s", param.Name))
		}
	}

	// Generate the function call
	var callStr string
	if fn.IsMethod {
		if fn.Receiver.Generic != nil && len(fn.Receiver.Generic.Args) > 0 {
			// For generic methods
			callStr = fmt.Sprintf("c.%s(%s)", fn.Name, strings.Join(callArgs, ", "))
		} else {
			callStr = fmt.Sprintf("c.%s(%s)", fn.Name, strings.Join(callArgs, ", "))
		}
	} else {
		// For generic functions
		if fn.IsGeneric {
			callStr = fmt.Sprintf("%s[string](%s)", fn.Name, strings.Join(callArgs, ", "))
		} else {
			callStr = fmt.Sprintf("%s(%s)", fn.Name, strings.Join(callArgs, ", "))
		}
	}

	numResults := len(fn.Results)

	if numResults == 0 {
		// No return values
		fmt.Fprintf(buf, "%s%s\n", indent, callStr)
	} else if numResults == 1 {
		result := fn.Results[0]
		if strings.HasPrefix(result.String(), "error") {
			// Single error return
			fmt.Fprintf(buf, "%serr := %s\n", indent, callStr)
			fmt.Fprintf(buf, "%sif err != nil {\n", indent)
			fmt.Fprintf(buf, "%s\tt.Errorf(\"%s() error = %%v, want nil\", err)\n", indent, fn.Name)
			fmt.Fprintf(buf, "%s}\n", indent)
		} else {
			// Single non-error return
			fmt.Fprintf(buf, "%sgot := %s\n", indent, callStr)
			if noSubtests {
				if g.opts.PrintInputs {
					// Build format string and args
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					format := fmt.Sprintf("%%q. %s(", fn.Name)
					args := []string{"tt.name"}
					for i, param := range fn.Params {
						if param.Name != "" {
							if i > 0 {
								format += ", "
							}
							format += "%v"
							args = append(args, fmt.Sprintf("tt.args.%s", param.Name))
						}
					}
					format += ") = %v, want %v"
					args = append(args, "got", "tt.want")

					fmt.Fprintf(buf, "%s\tt.Errorf(\"%s\"", indent, format)
					for _, arg := range args {
						fmt.Fprintf(buf, ", %s", arg)
					}
					fmt.Fprintf(buf, ")\n")
					fmt.Fprintf(buf, "%s}\n", indent)
				} else {
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%%q. %s() = %%v, want %%v\", tt.name, got, tt.want)\n", indent, fn.Name)
					fmt.Fprintf(buf, "%s}\n", indent)
				}
			} else {
				if g.opts.PrintInputs {
					// Build format string and args
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					format := fn.Name + "("
					args := []string{}
					for i, param := range fn.Params {
						if param.Name != "" {
							if i > 0 {
								format += ", "
							}
							format += "%v"
							args = append(args, fmt.Sprintf("tt.args.%s", param.Name))
						}
					}
					format += ") = %v, want %v"
					args = append(args, "got", "tt.want")

					fmt.Fprintf(buf, "%s\tt.Errorf(\"%s\"", indent, format)
					for _, arg := range args {
						fmt.Fprintf(buf, ", %s", arg)
					}
					fmt.Fprintf(buf, ")\n")
					fmt.Fprintf(buf, "%s}\n", indent)
				} else {
					fmt.Fprintf(buf, "%sif got != tt.want {\n", indent)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%s() = %%v, want %%v\", got, tt.want)\n", indent, fn.Name)
					fmt.Fprintf(buf, "%s}\n", indent)
				}
			}
		}
	} else {
		// Multiple return values - check for error
		hasError := false
		errorIdx := -1
		for i, result := range fn.Results {
			if strings.HasPrefix(result.String(), "error") {
				hasError = true
				errorIdx = i
				break
			}
		}

		resultVars := []string{}
		for i := range fn.Results {
			resultVars = append(resultVars, fmt.Sprintf("got%d", i))
		}

		fmt.Fprintf(buf, "%s%s := %s\n", indent, strings.Join(resultVars, ", "), callStr)

		if hasError {
			fmt.Fprintf(buf, "%sif (got%d != nil) != tt.wantErr {\n", indent, errorIdx)
			fmt.Fprintf(buf, "%s\tt.Fatalf(\"%s() error = %%v, wantErr %%v\", got%d, tt.wantErr)\n", indent, fn.Name, errorIdx)
			fmt.Fprintf(buf, "%s}\n", indent)
			fmt.Fprintf(buf, "%sif tt.wantErr {\n", indent)
			fmt.Fprintf(buf, "%s\treturn\n", indent)
			fmt.Fprintf(buf, "%s}\n", indent)

			// Check other return values
			for i, result := range fn.Results {
				if !strings.HasPrefix(result.String(), "error") {
					varName := resultVars[i]
					fmt.Fprintf(buf, "%sif %s != tt.want {\n", indent, varName)
					fmt.Fprintf(buf, "%s\tt.Errorf(\"%s() = %%v, want %%v\", %s, tt.want)\n", indent, fn.Name, varName)
					fmt.Fprintf(buf, "%s}\n", indent)
				}
			}
		} else {
			// No error return - compare all values
			for i, result := range fn.Results {
				varName := resultVars[i]
				wantName := fmt.Sprintf("want%d", i)
				fmt.Fprintf(buf, "%sif %s != tt.%s {\n", indent, varName, wantName)
				fmt.Fprintf(buf, "%s\tt.Errorf(\"%s() %s = %%v, want %%v\", %s, tt.%s)\n", indent, fn.Name, result.String(), varName, wantName)
				fmt.Fprintf(buf, "%s}\n", indent)
			}
		}
	}
}

// substituteTypeParams replaces type parameter references with concrete types
func (g *Generator) substituteTypeParams(typeInfo *TypeInfo, typeParams []string) *TypeInfo {
	// Create a copy to avoid modifying the original
	result := &TypeInfo{
		Name:       typeInfo.Name,
		IsPointer:  typeInfo.IsPointer,
		IsSlice:    typeInfo.IsSlice,
		IsMap:      typeInfo.IsMap,
		IsVariadic: typeInfo.IsVariadic,
		Generic:    typeInfo.Generic,
		Fields:     typeInfo.Fields,
	}

	// If this is a simple type parameter, replace it with "string"
	if result.Name == "T" || (len(typeParams) > 0 && result.Name == typeParams[0]) {
		result.Name = "string"
	}

	return result
}

func (g *Generator) getReceiverTypeName(recv *TypeInfo) string {
	if recv.Generic != nil && len(recv.Generic.Args) > 0 {
		args := strings.Join(recv.Generic.Args, ", ")
		return fmt.Sprintf("*%s[%s]", recv.Generic.Name, args)
	}
	name := recv.Name
	if recv.IsPointer {
		name = strings.TrimPrefix(name, "*")
	}
	return "*" + name
}

func (g *Generator) getReceiverTypeNameNoPtr(recv *TypeInfo) string {
	if recv.Generic != nil && len(recv.Generic.Args) > 0 {
		args := strings.Join(recv.Generic.Args, ", ")
		// Substitute T with string
		if args == "T" {
			args = "string"
		}
		return fmt.Sprintf("%s[%s]", recv.Generic.Name, args)
	}
	name := recv.Name
	if recv.IsPointer {
		name = strings.TrimPrefix(name, "*")
	}
	return name
}
